export const MAX=9007199254740991;
export class Fault extends Error{constructor(code,detail=''){super(code+(detail?': '+detail:''));this.code=code;this.kind='fault';}}
export class Refusal extends Error{constructor(code,origin){super(code);this.code=code;this.origin=origin;this.kind='refused';}}
export const scalar=s=>typeof s==='string'&&!/[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/u.test(s);
export function compare(a,b){const x=Array.from(a),y=Array.from(b);for(let i=0;i<Math.min(x.length,y.length);i++){let d=x[i].codePointAt(0)-y[i].codePointAt(0);if(d)return Math.sign(d)}return Math.sign(x.length-y.length)}
export function value(v,depth=0,seen=new Set()){if(depth>64)throw new Fault('ResourceLimit','value depth');if(typeof v==='boolean'||(typeof v==='number'&&Number.isSafeInteger(v))||scalar(v))return;if(!v||typeof v!=='object'||seen.has(v))throw new Fault('InputShape');seen.add(v);if(Array.isArray(v)){if(v.length>50000)throw new Fault('ResourceLimit','list length');v.forEach(x=>value(x,depth+1,seen))}else{if(![Object.prototype,null].includes(Object.getPrototypeOf(v)))throw new Fault('InputShape','host object');for(const k of Object.keys(v)){if(!scalar(k))throw new Fault('InputShape','key');value(v[k],depth+1,seen)}}seen.delete(v)}
export function tagged(v){if(typeof v==='boolean')return ['b',v];if(typeof v==='number')return ['i',String(v===0?0:v)];if(typeof v==='string')return ['s',v];if(Array.isArray(v))return ['l',v.map(tagged)];return ['r',Object.keys(v).sort(compare).map(k=>[k,tagged(v[k])])];}
export function canon(v){value(v);return JSON.stringify(tagged(v))}
export function json(v){value(v);if(Array.isArray(v))return '['+v.map(json).join(',')+']';if(v&&typeof v==='object')return '{'+Object.keys(v).sort(compare).map(k=>JSON.stringify(k)+':'+json(v[k])).join(',')+'}';return JSON.stringify(v)}
export function shape(v,t,types={},seen=new Set()){if(typeof t==='string'){if(t==='Any')return true;if(t==='Int')return typeof v==='number'&&Number.isSafeInteger(v);if(t==='Text')return scalar(v);if(t==='Bool')return typeof v==='boolean';if(!Object.hasOwn(types,t)||seen.has(t))throw new Fault('TypeDefinition',t);return shape(v,types[t],types,new Set([...seen,t]))}
 if(!t||typeof t!=='object')throw new Fault('TypeDefinition');if(t.list!==undefined)return Array.isArray(v)&&v.every(x=>shape(x,t.list,types,seen));if(t.enum)return t.enum.some(x=>canon(v)===canon(x));if(t.fields){if(!v||typeof v!=='object'||Array.isArray(v))return false;return Object.keys(v).length===Object.keys(t.fields).length&&Object.entries(t.fields).every(([k,s])=>Object.hasOwn(v,k)&&shape(v[k],s,types,seen))}throw new Fault('TypeDefinition');}
export function exact(n){if(n>BigInt(MAX)||n< -BigInt(MAX))throw new Fault('ArithmeticOverflow');return Number(n)}
export function floor(a,b){if(b===0)throw new Refusal('DivideByZero','div');let x=BigInt(a),y=BigInt(b),q=x/y,r=x%y;return r!==0n&&((r<0n)!==(y<0n))?q-1n:q}
export function csv(text){let s=text.charCodeAt(0)===0xfeff?text.slice(1):text;if(new TextEncoder().encode(text).length>1048576)throw new Refusal('FileTooLarge','csv');let rows=[],row=[],field='',quoted=false,closed=false,start=true;
 const push=()=>{row.push(field);field='';closed=false;start=true};const end=()=>{push();rows.push(row);row=[];if(rows.length>10001)throw new Refusal('TooManyRows','csv')};
 for(let i=0;i<s.length;i++){let c=s[i];if(quoted){if(c==='"'){if(s[i+1]==='"'){field+='"';i++}else{quoted=false;closed=true}}else field+=c;continue}
 if(closed&&c!==','&&c!=='\r'&&c!=='\n')throw new Refusal('MalformedCSV','csv');if(c==='"'){if(!start)throw new Refusal('MalformedCSV','csv');quoted=true;start=false}else if(c===',')push();else if(c==='\n')end();else if(c==='\r'){if(s[i+1]!=='\n')throw new Refusal('MalformedCSV','csv');i++;end()}else{field+=c;start=false}}
 if(quoted)throw new Refusal('MalformedCSV','csv');if(field!==''||closed||row.length||s.endsWith(','))end();return rows;}
